from openpyxl import load_workbook, Workbook
from openpyxl.utils import get_column_letter
import re

def parse_date(date_str):
    return date_str

def parse_account_ref(account_ref):
    match = re.match(r'^(CASH|PUR) (.+)$', account_ref)
    if match:
        return {
            'type': match.group(1),
            'item': match.group(2)
        }
    return {
        'type': 'UNKNOWN',
        'item': account_ref
    }

def process_sheet(sheet_name, wb):
    sheet = wb[sheet_name]
    header_row = None
    data_rows = []

    for row in sheet.iter_rows(min_row=1, max_row=sheet.max_row, min_col=1, max_col=sheet.max_col):
        if not header_row:
            header_row = [cell.value for cell in row]
        else:
            row_data = [cell.value for cell in row]
            data_rows.append(row_data)

    if not header_row or not data_rows:
        return

    date_col = header_row.index('DATE')
    account_ref_col = header_row.index('ACCOUNT REF')
    debit_col = header_row.index('DEBIT')
    credit_col = header_row.index('CREDIT')

    account_data = []
    for row in data_rows:
        date = parse_date(row[date_col])
        account_ref = row[account_ref_col]
        debit = row[debit_col]
        credit = row[credit_col]

        account_info = parse_account_ref(account_ref)
        account_type = account_info['type']
        item = account_info['item']

        if account_type == 'PUR':
            amount = credit if credit is not None else 0
            account_data.append((item, amount))

    return account_data

def aggregate_data(account_data):
    aggregated = {}
    for item, amount in account_data:
        if item not in aggregated:
            aggregated[item] = 0
        aggregated[item] += amount
    return aggregated

def write_to_out_cas(wb, aggregated_data):
    out_cas_sheet = wb.create_sheet(title='OUT CAS')

    # Clear existing data
    for row in out_cas_sheet.iter_rows():
        for cell in row:
            cell.value = None

    # Write headers
    headers = ['ITEM', 'AMOUNT', 'DATE']
    for col_num, header in enumerate(headers, 1):
        out_cas_sheet.cell(row=1, column=col_num, value=header)

    # Write data
    row_num = 2
    for item, amount in sorted(aggregated_data.items()):
        out_cas_sheet.cell(row=row_num, column=1, value=item)
        out_cas_sheet.cell(row=row_num, column=2, value=amount)
        out_cas_sheet.cell(row=row_num, column=3, value='2023-04-01')  # Placeholder date
        row_num += 1

    # Set column widths
    out_cas_sheet.column_dimensions['A'].width = 20
    out_cas_sheet.column_dimensions['B'].width = 15
    out_cas_sheet.column_dimensions['C'].width = 20

def main():
    input_wb = load_workbook('input.xlsx')
    sheets_to_process = ['CMSN', 'CSTR']

    aggregated_data = {}

    for sheet_name in sheets_to_process:
        sheet_data = process_sheet(sheet_name, input_wb)
        if sheet_data:
            aggregated_data.update(aggregate_data(sheet_data))

    # Create new workbook for output
    output_wb = Workbook()
    write_to_out_cas(output_wb, aggregated_data)

    # Save the output workbook
    output_wb.save('output.xlsx')

if __name__ == '__main__':
    main()
