import re

def process_worksheet(wb, sheet_name):
    # Load the worksheet
    ws = wb[sheet_name]

    # Ensure calculation is set to automatic
    ws.sheet_state = 'visible'

    # Convert any text-stored formulas back to formulas
    for row in ws.iter_rows():
        for cell in row:
            if cell.data_type == 'f' and cell.value is None:
                cell.value = f"={cell.coordinate}"

    # Set calculation mode to automatic
    ws.sheet_view.calculationMode = 'automatic'

    # Find the header row and first data row
    header_row = None
    data_start_row = None
    for row in ws.iter_rows(min_row=1, max_row=250):
        if all(cell.value is None for cell in row):
            continue
        if header_row is None:
            header_row = row[0].row
        else:
            data_start_row = row[0].row
            break

    if data_start_row is None:
        data_start_row = 250

    # Find all blocks
    blocks = []
    current_block_start = data_start_row
    for row in ws.iter_rows(min_row=data_start_row, max_row=250):
        if row[0].value is None:
            if current_block_start <= row[0].row - 1:
                blocks.append((current_block_start, row[0].row - 1))
            current_block_start = row[0].row + 1

    if current_block_start <= 250:
        blocks.append((current_block_start, 250))

    # Process each block
    for block_start, block_end in blocks:
        # Extract data rows
        data_rows = []
        for row in ws.iter_rows(min_row=block_start, max_row=block_end):
            if row[0].value is not None:
                data_rows.append(row)

        # Sort data rows by column D (index 3) in descending order
        data_rows.sort(key=lambda x: float(x[3].value), reverse=True)

        # Write sorted data back to the worksheet
        for i, row in enumerate(data_rows):
            for j, cell in enumerate(row):
                ws.cell(row=block_start + i, column=j + 1, value=cell.value)

    # Apply number formatting to columns D, E, F
    for row in ws.iter_rows(min_row=1, max_row=250):
        for col in [3, 4, 5]:  # Columns D, E, F
            cell = row[col]
            if cell.data_type == 'n':
                cell.number_format = '0.0'
                if cell.value == int(cell.value):
                    cell.number_format = '0'

    # Apply bold and center alignment to columns D, E, F
    for row in ws.iter_rows(min_row=1, max_row=250):
        for col in [3, 4, 5]:  # Columns D, E, F
            cell = row[col]
            cell.font = Font(bold=True)
            cell.alignment = Alignment(horizontal='center', vertical='center')

    # Ensure all formatting is preserved
    for row in ws.iter_rows():
        for cell in row:
            if cell.has_style:
                ws.cell(row=cell.row, column=cell.column).font = cell.font
                ws.cell(row=cell.row, column=cell.column).alignment = cell.alignment
                ws.cell(row=cell.row, column=cell.column).number_format = cell.number_format

    # Ensure column widths are preserved
    for col in ws.columns:
        max_length = 0
        column = col[0].column_letter
        for cell in col:
            if cell.value:
                try:
                    if len(str(cell.value)) > max_length:
                        max_length = len(str(cell.value))
                except:
                    pass
        ws.column_dimensions[column].width = max_length + 2

